// reference matcher: segments, literal > param > catchall, with backtracking
type refRoute struct {
	segs []string
	path string
}

func refMatch(routes []refRoute, reqPath string) (string, map[string]string, bool) {
	reqSegs := strings.Split(strings.TrimPrefix(reqPath, "/"), "/")
	if reqPath == "/" {
		reqSegs = []string{""}
	}
	var best string
	var bestParams map[string]string
	found := false
	var dfs func(ri, si int, params map[string]string) bool
	dfs = func(ri, si int, params map[string]string) bool {
		if ri == len(routes) {
			return false
		}
		return false
	}
	_ = dfs
	for _, r := range routes {
		params := map[string]string{}
		ok := matchSegs(r.segs, reqSegs, params)
		if ok {
			if !found {
				found = true
				best = r.path
				bestParams = params
			}
		}
	}
	return best, bestParams, found
}

func matchSegs(route, req []string, params map[string]string) bool {
	// DFS with preference literal > param > catchall
	if len(route) == 0 {
		return len(req) == 0
	}
	seg := route[0]
	switch {
	case seg == "*w":
		params["w"] = "/" + strings.Join(req, "/")
		return true
	case strings.HasPrefix(seg, ":"):
		if len(req) == 0 || req[0] == "" {
			return false
		}
		params[seg[1:]] = req[0]
		if matchSegs(route[1:], req[1:], params) {
			return true
		}
		delete(params, seg[1:])
		return false
	default:
		if len(req) == 0 || req[0] != seg {
			return false
		}
		return matchSegs(route[1:], req[1:], params)
	}
}

