type refTrie struct {
	lit      map[string]*refTrie
	param    *refTrie
	paramKey string
	catchAll *refTrie
	path     string
	hasH     bool
}

func newRefTrie() *refTrie { return &refTrie{lit: map[string]*refTrie{}} }

func (t *refTrie) add(segs []string, path string) {
	if len(segs) == 0 {
		t.hasH = true
		t.path = path
		return
	}
	s := segs[0]
	switch {
	case s == "*w":
		if t.catchAll == nil {
			t.catchAll = newRefTrie()
		}
		t.catchAll.hasH = true
		t.catchAll.path = path
	case strings.HasPrefix(s, ":"):
		if t.param == nil {
			t.param = newRefTrie()
			t.paramKey = s[1:]
		}
		t.param.add(segs[1:], path)
	default:
		if t.lit[s] == nil {
			t.lit[s] = newRefTrie()
		}
		t.lit[s].add(segs[1:], path)
	}
}

// returns path, params, ok
func (t *refTrie) match(req []string, params map[string]string) (string, map[string]string, bool) {
	if len(req) == 0 {
		if t.hasH {
			cp := map[string]string{}
			for k, v := range params {
				cp[k] = v
			}
			return t.path, cp, true
		}
		return "", nil, false
	}
	// literal first
	if c := t.lit[req[0]]; c != nil {
		if p, ps, ok := c.match(req[1:], params); ok {
			return p, ps, ok
		}
	}
	// param
	if t.param != nil && req[0] != "" {
		params[t.paramKey] = req[0]
		if p, ps, ok := t.param.match(req[1:], params); ok {
			return p, ps, ok
		}
		delete(params, t.paramKey)
	}
	// catchall
	if t.catchAll != nil && t.catchAll.hasH {
		params["w"] = "/" + strings.Join(req, "/")
		cp := map[string]string{}
		for k, v := range params {
			cp[k] = v
		}
		return t.catchAll.path, cp, true
	}
	return "", nil, false
}

